.results-panel {
  display: none;
  border-radius: var(--radius);
  padding: 1.5rem;
  text-align: center;
  background: var(--color-success-bg);
  border: 1px solid #bbf7d0;
  margin-top: 2rem;
}

.results-panel.visible {
  display: block;
}

.results-panel h2 {
  font-size: 1.25rem;
