  {
    id: "q1",
    text: "Which of the following are statically typed programming languages?",
    helpText: "Select all that apply. A statically typed language checks types at compile time rather than runtime.",
    answers: [
      { id: "q1a", text: "Python", correct: false },
      { id: "q1b", text: "Java", correct: true },
      { id: "q1c", text: "C++", correct: true },
      { id: "q1d", text: "JavaScript", correct: false },
    ],
  },
  {
    id: "q2",
    text: "Which languages were originally designed by engineers at Google?",
    answers: [
      { id: "q2a", text: "Go", correct: true },
      { id: "q2b", text: "Kotlin", correct: false },
      { id: "q2c", text: "Dart", correct: true },
      { id: "q2d", text: "TypeScript", correct: false },
    ],
  },
  {
    id: "q3",
    text: "Which of the following languages use automatic garbage collection?",
    answers: [
      { id: "q3a", text: "C", correct: false },
      { id: "q3b", text: "Java", correct: true },
      { id: "q3c", text: "Python", correct: true },
      { id: "q3d", text: "Go", correct: true },
    ],
  },
];

const form = document.getElementById("quiz-form");
const progressFill = document.getElementById("progress-fill");
const progressAnswered = document.getElementById("progress-answered");
const validationSummary = document.getElementById("validation-summary");
const resultsPanel = document.getElementById("results-panel");
const scoreBadge = document.getElementById("score-badge");
const resultsMsg = document.getElementById("results-msg");

function getAnsweredCount() {
  return QUESTIONS.filter((q) =>
    q.answers.some((a) => document.getElementById(a.id)?.checked)
  ).length;
}

function updateProgress() {
  const answered = getAnsweredCount();
  const total = QUESTIONS.length;
  const pct = Math.round((answered / total) * 100);
  progressFill.style.width = `${pct}%`;
  progressAnswered.textContent = `${answered} / ${total} answered`;
}

function validateForm() {
  const unanswered = QUESTIONS.filter(
    (q) => !q.answers.some((a) => document.getElementById(a.id)?.checked)
  );
  return unanswered;
}

function scoreQuiz() {
  let score = 0;
  QUESTIONS.forEach((q) => {
    const selected = new Set(
      q.answers.filter((a) => document.getElementById(a.id)?.checked).map((a) => a.id)
    );
    const correct = new Set(q.answers.filter((a) => a.correct).map((a) => a.id));
    const isFullyCorrect =
      selected.size === correct.size && [...selected].every((id) => correct.has(id));
    if (isFullyCorrect) score++;

    // Visual feedback per choice
    q.answers.forEach((a) => {
      const item = document.getElementById(a.id)?.closest(".choice-item");
      if (!item) return;
      if (a.correct) {
        item.classList.add("correct");
      } else if (selected.has(a.id)) {
        item.classList.add("incorrect");
      }
    });
  });
  return score;
}

form.addEventListener("change", updateProgress);

form.addEventListener("submit", (e) => {
  e.preventDefault();

  const unanswered = validateForm();
  if (unanswered.length > 0) {
    const labels = unanswered
      .map((q) => {
        const legend = document.querySelector(`#${q.id}-fieldset legend`);
        return legend ? `"${legend.textContent.trim()}"` : q.id;
      })
      .join("; ");
    validationSummary.textContent = `Please answer all questions before submitting. Unanswered: ${labels}`;
    validationSummary.style.display = "block";

    // Focus the first unanswered question's first checkbox
    const firstUnansweredInput = document.getElementById(unanswered[0].answers[0].id);
    firstUnansweredInput?.focus();
    return;
  }

  validationSummary.style.display = "none";
  form.classList.add("submitted");

  const score = scoreQuiz();
  const total = QUESTIONS.length;
  scoreBadge.textContent = `${score}/${total}`;
  resultsMsg.textContent =
    score === total
      ? "Perfect score! Excellent knowledge of programming languages."
      : score >= 2
      ? "Great job! You know your programming languages well."
      : "Good effort! Review the highlighted answers to learn more.";

  resultsPanel.classList.add("visible");
  resultsPanel.scrollIntoView({ behavior: "smooth", block: "nearest" });
  resultsPanel.focus();

  // Disable submit
  document.getElementById("btn-submit").disabled = true;
  document.getElementById("btn-submit").setAttribute("aria-disabled", "true");
});
